INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_SATANISM','Modern Organized Satanism (1966-present)',1966,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_LAVEY_SATANIC_BIBLE','primary text','Anton Szandor LaVey, The Satanic Bible (1969)','Foundational text of the Church of Satan; LaVeyan symbolic Satanism, the self as god, the Four Crown Princes of Hell, the Sigil of Baphomet.'),
 ('SRC_PETERSEN_RELIGIOUS_SATANISM','secondary scholarship','Jesper Aagaard Petersen (ed.), Contemporary Religious Satanism: A Critical Anthology (2009)','Scholarly survey of organized/practiced Satanism: Church of Satan, theistic Satanism, Temple of Set, Luciferianism, The Satanic Temple.')
INSERT INTO _e VALUES
 ('ENT_SAT_MOVEMENT','Modern Satanism','Religious movement / collective','Religious movement / collective','Modern Satanism','adversary, self-deification, individualism','B','Hub collective for organized, practiced modern Satanism from the founding of the Church of Satan (1966) onward; encompasses LaVeyan symbolic Satanism, theistic Satanism, Luciferianism, and the Setian current.'),
 ('ENT_SAT_LAVEYAN_SATAN','Satan (LaVeyan / symbolic adversary)','Symbolic figure / archetype','Symbolic figure / archetype','Modern Satanism','adversary, carnality, autonomy, the self','B','In Church of Satan doctrine (LaVey 1969) Satan is not a literal being but a symbol of the carnal self, pride, rational self-interest and the adversarial principle; venerated rhetorically as the embodiment of human nature and self-deification. Modeled neutrally as the movement''s symbolic reception of the adversary.'),
 ('ENT_SAT_FOUR_CROWN_PRINCES','Four Crown Princes of Hell','Collective / grouping','Collective / grouping','Modern Satanism','the four directions, infernal hierarchy','B','LaVey''s fourfold grouping invoked in Church of Satan ritual (The Satanic Bible, 1969): Satan (south/fire), Lucifer (east/air), Belial (north/earth), Leviathan (west/water). Collective wiring the existing demon-entities; not a re-creation of any of the four.'),
 ('ENT_SAT_THEISTIC_SATAN','Satan (theistic Satanism)','Deity (as believed)','Deity (as believed)','Modern Satanism','adversary, liberation, dark divinity','C','Within theistic (traditional/devotional) Satanism, held by adherents to be a literal divine being and object of worship and devotion, distinct from the Church of Satan''s purely symbolic reading. Modeled neutrally as a belief held within the movement.'),
 ('ENT_SAT_LUCIFERIAN_LUCIFER','Lucifer (Luciferian light-bringer)','Symbolic figure / venerated being','Symbolic figure / venerated being','Modern Satanism','light, knowledge, liberation, the morning star','C','In modern Luciferianism, Lucifer is venerated as the bringer of light and forbidden knowledge and a figure of self-liberation and enlightenment, framed positively rather than as the Christian devil; held devotionally or symbolically depending on the practitioner. Reception of the existing Lucifer.'),
 ('ENT_SAT_SETIAN_SET','Set (Temple of Set)','Deity (as believed)','Deity (as believed)','Modern Satanism','isolate self-consciousness, individuation, xeper (becoming)','B','Following Michael Aquino''s founding of the Temple of Set (1975) as a schism from the Church of Satan, the Egyptian god Set is held to be a real, enduring divine intelligence and patron of the isolate, self-aware psyche; Setians pursue ''Xeper'' (self-deification). Reception of the existing Egyptian Set/Seth.');
