INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_SAT_MOVEMENT','PER_MODERN_SATANISM','Hub collective for organized, practiced modern Satanism from the founding of the Church of Satan (1966) onward; encompasses LaVeyan symbolic Satanism, theistic Satanism, Luciferianism, and the Setian current.'),
 ('ENT_SAT_LAVEYAN_SATAN','PER_MODERN_SATANISM','In Church of Satan doctrine (LaVey 1969) Satan is not a literal being but a symbol of the carnal self, pride, rational self-interest and the adversarial principle; venerated rhetorically as the embodiment of human nature and self-deification. Modeled neutrally as the movement''s symbolic reception of the adversary.'),
 ('ENT_SAT_FOUR_CROWN_PRINCES','PER_MODERN_SATANISM','LaVey''s fourfold grouping invoked in Church of Satan ritual (The Satanic Bible, 1969): Satan (south/fire), Lucifer (east/air), Belial (north/earth), Leviathan (west/water). Collective wiring the existing demon-entities; not a re-creation of any of the four.'),
 ('ENT_SAT_THEISTIC_SATAN','PER_MODERN_SATANISM','Within theistic (traditional/devotional) Satanism, held by adherents to be a literal divine being and object of worship and devotion, distinct from the Church of Satan''s purely symbolic reading. Modeled neutrally as a belief held within the movement.'),
 ('ENT_SAT_LUCIFERIAN_LUCIFER','PER_MODERN_SATANISM','In modern Luciferianism, Lucifer is venerated as the bringer of light and forbidden knowledge and a figure of self-liberation and enlightenment, framed positively rather than as the Christian devil; held devotionally or symbolically depending on the practitioner. Reception of the existing Lucifer.'),
 ('ENT_SAT_SETIAN_SET','PER_MODERN_SATANISM','Following Michael Aquino''s founding of the Temple of Set (1975) as a schism from the Church of Satan, the Egyptian god Set is held to be a real, enduring divine intelligence and patron of the isolate, self-aware psyche; Setians pursue ''Xeper'' (self-deification). Reception of the existing Egyptian Set/Seth.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_SAT_LAVEYAN_SATAN','member_of','ENT_SAT_MOVEMENT','high','The LaVeyan symbolic Satan is the central figure of the Church of Satan, the founding body of organized modern Satanism.'),
 ('ENT_SAT_FOUR_CROWN_PRINCES','member_of','ENT_SAT_MOVEMENT','high','The Four Crown Princes are a doctrinal/ritual grouping of the Church of Satan within the modern Satanism movement.'),
 ('ENT_SAT_THEISTIC_SATAN','member_of','ENT_SAT_MOVEMENT','high','Theistic Satanism''s worshipped Satan belongs to the broad modern Satanism movement as its devotional/literalist current.'),
 ('ENT_SAT_LUCIFERIAN_LUCIFER','member_of','ENT_SAT_MOVEMENT','high','Luciferianism is a recognized current within the modern Satanism movement.'),
 ('ENT_SAT_SETIAN_SET','member_of','ENT_SAT_MOVEMENT','high','The Temple of Set''s Set is the focal deity of the Setian current, a schismatic offshoot within organized modern Satanism.'),
 ('ENT_ISR_SATAN','member_of','ENT_SAT_FOUR_CROWN_PRINCES','high','Satan is the first of LaVey''s Four Crown Princes of Hell (south, fire); wiring the existing Satan entity into the collective rather than recreating it.'),
 ('ENT_CHR_LUCIFER','member_of','ENT_SAT_FOUR_CROWN_PRINCES','high','Lucifer is named by LaVey as a Crown Prince of Hell (east, air); existing Lucifer entity wired into the collective.'),
 ('ENT_ISR_BELIAL','member_of','ENT_SAT_FOUR_CROWN_PRINCES','high','Belial is named by LaVey as a Crown Prince of Hell (north, earth); existing Belial entity wired into the collective.'),
 ('ENT_ISR_LEVIATHAN','member_of','ENT_SAT_FOUR_CROWN_PRINCES','high','Leviathan is named by LaVey as a Crown Prince of Hell (west, water); existing Leviathan entity wired into the collective.'),
 ('ENT_SAT_LAVEYAN_SATAN','reception_of','ENT_ISR_SATAN','high','The LaVeyan symbolic adversary is a modern reinterpretation of the biblical/Second-Temple Satan, stripped of literal existence and recast as the carnal self.'),
 ('ENT_SAT_THEISTIC_SATAN','reception_of','ENT_ISR_SATAN','high','Theistic Satanism''s worshipped Satan is a devotional reception of the biblical/Second-Temple adversary as a literal deity.'),
 ('ENT_SAT_LUCIFERIAN_LUCIFER','reception_of','ENT_CHR_LUCIFER','high','The Luciferian light-bringer is a positive modern reception of the Christian-reception Lucifer, inverting the fallen-angel narrative into one of enlightenment.'),
 ('ENT_SAT_SETIAN_SET','reception_of','ENT_EGY_SETH','high','The Temple of Set venerates the Egyptian god Set/Seth as a real divine intelligence; Aquino''s Setian Set is a modern reception of the ancient Egyptian deity.'),
 ('ENT_SAT_MOVEMENT','symbolized_by','ENT_REC_BAPHOMET_LEVI','high','The Sigil of Baphomet (goat''s-head pentagram) derived from Lévi''s Baphomet is the emblem of the Church of Satan and broader modern Satanism.'),
 ('ENT_SAT_LAVEYAN_SATAN','associated_with','ENT_REC_BAPHOMET_LEVI','high','LaVey adopted Lévi''s Baphomet as the iconographic Sigil of Baphomet representing Satan in Church of Satan ritual.'),
 ('ENT_SAT_SETIAN_SET','opposes','ENT_SAT_LAVEYAN_SATAN','medium','The Temple of Set defined itself in schism from the Church of Satan (1975), rejecting LaVey''s purely symbolic Satan in favor of a literal deity Set; doctrinal opposition between the two currents.');
